import {safeContentLink,validContentText} from './content-rules.js';
export async function openContentEditor({sb,host,editor,status,isCurrent}){
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const inventory=await fetch('/assets/content-inventory.json').then(r=>{if(!r.ok)throw Error('Content catalogue could not load.');return r.json()});
 if(!isCurrent())return;
 host.innerHTML=`<section class="app-card"><h2>Page content</h2><p>Edit headings, body copy and links. Changes preserve the page layout. Guest profiles and announcements have their own tabs. Legal text, form labels and homepage copy are kept in the source.</p><div class="content-filters"><label>Page<select id="content-page">${[...new Set(inventory.map(r=>r.page))].map(p=>`<option>${escape(p)}</option>`).join('')}</select></label><label>Find text<input id="content-search" type="search" placeholder="Search this page"></label></div><div id="content-list"></div></section>`;editor.replaceChildren();
 const page=host.querySelector('#content-page'),search=host.querySelector('#content-search'),list=host.querySelector('#content-list');let rows=new Map(),generation=0;
 function render(){list.innerHTML=inventory.filter(r=>r.page===page.value&&r.text.toLowerCase().includes(search.value.toLowerCase())).map(r=>`<button class="content-choice secondary" data-key="${r.key}"><small>${r.tag==='a'?'LINK':r.tag.toUpperCase()}${rows.get(r.key)?.published?' · EDITED':''}</small><span>${escape(rows.get(r.key)?.published?rows.get(r.key).text:r.text)}</span></button>`).join('')||'<p>No matching text.</p>';list.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>edit(inventory.find(r=>r.key===b.dataset.key)));}
 async function load(){const version=++generation;editor.replaceChildren();status('Loading page content…');const r=await sb.from('elan_page_content').select('*').eq('page',page.value);if(!isCurrent()||version!==generation)return;if(r.error){status('Page editor could not connect: '+r.error.message,true);return;}rows=new Map(r.data.map(r=>[r.key,r]));render();status('Choose a passage to edit.');}
 function edit(item){const old=rows.get(item.key);editor.innerHTML=`<section class="app-card"><h2>Edit ${escape(item.page)}</h2><details><summary>Original text</summary><p>${escape(item.text)}</p></details><form id="page-copy-form" class="app-form"><label>Text<textarea name="text" required maxlength="6000">${escape(old?.published?old.text:item.text)}</textarea></label>${item.href!==null?`<label>Link destination<input name="href" required maxlength="2000" value="${escape(old?.published?old.href||item.href:item.href)}"></label>`:''}<p>Preview</p><p class="content-preview"></p><button type="submit">Publish change</button><button type="button" id="restore-copy" class="secondary" ${old?.published?'':'disabled'}>Restore original</button></form><p>Refresh the public page after saving. Changes to page titles and search descriptions still require a source update.</p></section>`;
 const form=editor.querySelector('form'),preview=editor.querySelector('.content-preview');const refresh=()=>preview.textContent=form.elements.text.value;form.elements.text.oninput=refresh;refresh();
 async function save(restore=false){const text=form.elements.text.value.trim(),href=form.elements.href?.value.trim()||null;if(!validContentText(text))throw Error('Enter between 1 and 6,000 characters.');if(href&&!safeContentLink(href))throw Error('Use a site path, https:// link, mailto: address or tel: number.');const r=await sb.from('elan_page_content').upsert({key:item.key,page:item.page,text,href,published:!restore,updated_at:new Date().toISOString()}).select().single();if(r.error)throw r.error;await load();status(restore?'Original content restored.':'Published. Refresh the public page to see your change.');}
 async function submit(restore){const buttons=form.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);status('Saving…');try{await save(restore)}catch(e){status(e.message,true)}finally{buttons.forEach(b=>b.disabled=false)}}
 form.onsubmit=e=>{e.preventDefault();if(form.reportValidity())submit(false)};form.querySelector('#restore-copy').onclick=()=>submit(true);editor.scrollIntoView({block:'start'});
 }
 page.onchange=()=>load().catch(e=>status(e.message,true));search.oninput=render;await load();
}
